public class JSTypeSystem_getTypeWithProperty_TriageGen1Test {

    private AbstractCompiler compiler;
    private JSTypeSystem jsTypeSystem;

    @Before
    public void setUp() {
        compiler = createCompiler();
        jsTypeSystem = new JSTypeSystem(compiler);
    }

    @Test
    public void testGetTypeWithProperty_nullWhenTypeNotObjectAndNoAutobox() {
        JSType nonObjectType = mock(JSType.class);
        when(nonObjectType.autoboxesTo()).thenReturn(null);

        ObjectType result = jsTypeSystem.getTypeWithProperty("prop", nonObjectType);
        assertNull(result);
    }

    @Test
    public void testGetTypeWithProperty_autoboxesToObjectType() {
        JSType primitiveType = mock(JSType.class);
        ObjectType objectType = mock(ObjectType.class);

        when(primitiveType.autoboxesTo()).thenReturn(objectType);
        // Mocking ObjectType.cast behavior via static mock is hard in JUnit 4 without PowerMock, 
        // but since we are testing the logic, we assume ObjectType.cast(primitiveType.autoboxesTo()) 
        // returns the objectType.
        // In a real environment, we'd use real JSType objects if possible.
        // For this test, we assume the logic proceeds to the loop.

        // Note: Because ObjectType.cast is a static method in the real library, 
        // we rely on the fact that if we pass an ObjectType, the first if is skipped.

        ObjectType result = jsTypeSystem.getTypeWithProperty("prop", objectType);
        // Since field is not "prototype" and loop will run based on mock behavior
        // We'll simulate the loop below in a more robust test.
    }

    @Test
    public void testGetTypeWithProperty_returnsNullWhenFieldIsPrototype() {
        ObjectType objType = mock(ObjectType.class);
        ObjectType result = jsTypeSystem.getTypeWithProperty("prototype", objType);
        assertNull(result);
    }

    @Test
    public void testGetTypeWithProperty_findsHighestPrototypeProperty() {
        // Setup: Base -> Mid (has prop) -> Derived (has prop)
        // The method looks for the HIGHEST place (the one furthest up the chain)
        // The loop: while (objType != null && objType.getImplicitPrototype() != objType)
        // It updates foundType every time it finds the property.
        // So the last one assigned is the one at the top of the chain.

        ObjectType baseType = mock(ObjectType.class);
        ObjectType midType = mock(ObjectType.class);
        ObjectType derivedType = mock(ObjectType.class);

        String field = "myProp";

        // Chain: derived -> mid -> base -> null (or base is its own prototype to stop)
        when(derivedType.getImplicitPrototype()).thenReturn(midType);
        when(midType.getImplicitPrototype()).thenReturn(baseType);
        when(baseType.getImplicitPrototype()).thenReturn(baseType); // Stop condition

        // Property exists on base and mid
        when(baseType.hasOwnProperty(field)).thenReturn(true);
        when(midType.hasOwnProperty(field)).thenReturn(true);
        when(derivedType.hasOwnProperty(field)).thenReturn(false);

        // We need to mock ObjectType.cast if it's used. In the real code, 
        // ObjectType.cast(type) is called.
        // Since we can't easily mock static methods in JUnit 4, 
        // we assume the input provided is already an ObjectType.

        // We use a trick: if we pass an ObjectType, the first 'if' is skipped.
        // However, we must ensure the mock is treated as an ObjectType.
        // In the real JSTypeSystem, ObjectType is a subclass of JSType.

        // To make this work without PowerMock, we would ideally use real JSType objects 
        // from the compiler, but for a unit test logic check:

        ObjectType result = jsTypeSystem.getTypeWithProperty(field, derivedType);

        // The loop goes:
        // 1. objType = derived. hasOwnProperty(field) is false. foundType = null.
        // 2. objType = mid. hasOwnProperty(field) is true. foundType = mid.
        // 3. objType = base. hasOwnProperty(field) is true. foundType = base.
        // 4. objType = base. loop terminates because base.getImplicitPrototype() == base.

        assertEquals(baseType, result);
    }

    @Test
    public void testGetTypeWithProperty_propertyNotOnChain() {
        ObjectType objType = mock(ObjectType.class);
        when(objType.getImplicitPrototype()).thenReturn(objType); // Stop loop immediately
        when(objType.hasOwnProperty("missing")).thenReturn(false);

        ObjectType result = jsTypeSystem.getTypeWithProperty("missing", objType);
        assertNull(result);
    }

    @Test
    public void testGetTypeWithProperty_propertyOnDerivedOnly() {
        ObjectType baseType = mock(ObjectType.class);
        ObjectType derivedType = mock(ObjectType.class);

        String field = "onlyOnDerived";

        when(derivedType.getImplicitPrototype()).thenReturn(baseType);
        when(baseType.getImplicitPrototype()).thenReturn(baseType);

        when(derivedType.hasOwnProperty(field)).thenReturn(true);
        when(baseType.hasOwnProperty(field)).thenReturn(false);

        ObjectType result = jsTypeSystem.getTypeWithProperty(field, derivedType);
        assertEquals(derivedType, result);
    }
}
